using System.Text.Json.Nodes;
using ClaimsIntake.Domain.Security;
using ClaimsIntake.Security.AspNetCore;
using Microsoft.AspNetCore.Authorization;
using Microsoft.OpenApi;

namespace ClaimsIntake.Api.Http;

/// <summary>
/// The OpenAPI document of the review API (API-02): the routes, the bearer security scheme, and for each operation the roles
/// that may call it. The document is generated by the framework and served at <c>/openapi/v1.json</c> in Development only; the
/// committed copy is <c>docs/openapi/review-api.v1.json</c>, and a test fails when the two differ.
/// </summary>
public static class OpenApiSetup
{
    public const string BearerScheme = "Bearer";
    public const string DocumentName = "v1";

    /// <summary>Which app roles satisfy each authorisation policy, for the documentation. The policies themselves stay the source of truth.</summary>
    private static readonly Dictionary<string, string[]> PolicyRoles = new(StringComparer.Ordinal)
    {
        [Policies.Handler] = [AppRoles.ClaimsHandler, AppRoles.SeniorHandler],
        [Policies.ReadHistory] = [AppRoles.IntakeReadHistory],
        [Policies.IntakeSubmit] = [AppRoles.IntakeSubmit],
    };

    public static IServiceCollection AddClaimsIntakeOpenApi(this IServiceCollection services)
    {
        services.AddOpenApi(DocumentName, options =>
        {
            options.AddDocumentTransformer((document, _, _) =>
            {
                document.Info = new OpenApiInfo
                {
                    Title = "Claims Intake review API",
                    Version = "v1",
                    Description = "The review queue for proposed claims: list, read, approve and reject. Every route needs a Microsoft Entra ID "
                        + "access token (bearer). People need the ClaimsHandler or SeniorHandler app role; a claim routed to senior review can only be "
                        + "approved by a SeniorHandler. /claims/history and /intake/claims take app-only tokens with their own roles. The health "
                        + "probes are anonymous. Errors are RFC 7807 problem details.",
                };
                // The host is not part of the contract: a deployment is reached at its own address.
                document.Servers = [];
                document.Components ??= new OpenApiComponents();
                document.Components.SecuritySchemes ??= new Dictionary<string, IOpenApiSecurityScheme>();
                document.Components.SecuritySchemes[BearerScheme] = new OpenApiSecurityScheme
                {
                    Type = SecuritySchemeType.Http,
                    Scheme = "bearer",
                    BearerFormat = "JWT",
                    Description = "A Microsoft Entra ID access token for this API. Roles come from the token's roles claim.",
                };
                return Task.CompletedTask;
            });

            options.AddOperationTransformer((operation, context, _) =>
            {
                var authorize = context.Description.ActionDescriptor.EndpointMetadata.OfType<IAuthorizeData>().ToList();
                var anonymous = context.Description.ActionDescriptor.EndpointMetadata.OfType<IAllowAnonymous>().Any();
                if (anonymous)
                {
                    return Task.CompletedTask;
                }

                // Every endpoint needs a signed-in caller (the fallback policy), whether or not it names a policy of its own.
                operation.Security ??= [];
                operation.Security.Add(new OpenApiSecurityRequirement
                {
                    [new OpenApiSecuritySchemeReference(BearerScheme, context.Document)] = [],
                });

                var roles = authorize
                    .Select(a => a.Policy)
                    .Where(p => p is not null && PolicyRoles.ContainsKey(p))
                    .SelectMany(p => PolicyRoles[p!])
                    .Distinct(StringComparer.Ordinal)
                    .ToArray();
                if (roles.Length > 0)
                {
                    operation.Extensions ??= new Dictionary<string, IOpenApiExtension>();
                    operation.Extensions["x-required-roles"] = new JsonNodeExtension(new JsonArray([.. roles.Select(r => (JsonNode)JsonValue.Create(r)!)]));
                    operation.Description = (operation.Description is { Length: > 0 } d ? d + " " : "")
                        + $"Requires one of the app roles: {string.Join(", ", roles)}.";
                }

                return Task.CompletedTask;
            });
        });
        return services;
    }
}
